with feeders as (
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__MD_SEQ_NO))) as HUB_RISK_OBJECT_HK
        , cast(null as varchar) as MEMBER_ADDITION_INDICATOR
        , MD_RELATION as RELATIONSHIP_TO_PROPOSER
        , cast(null as varchar) as MEMBER_TYPE
        , cast(null as varchar) as MEMBER_NAME
        , cast(null as varchar) as DATE_OF_BIRTH
        , cast(null as varchar) as GENDER
        , cast(null as varchar) as PASSPORT_NUMBER
        , cast(null as varchar) as PRE_EXISTING_DISEASE_DESCRIPTION
        , 'BA_HCP_PROD_8433_FHC_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8433_fhc_loader') }}
    where (nullif(trim(MD_SEQ_NO),'')) is not null
),

resolved as (
    select
        HUB_RISK_OBJECT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_ADDITION_INDICATOR end) as MEMBER_ADDITION_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RELATIONSHIP_TO_PROPOSER end) as RELATIONSHIP_TO_PROPOSER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_TYPE end) as MEMBER_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_NAME end) as MEMBER_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DATE_OF_BIRTH end) as DATE_OF_BIRTH,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GENDER end) as GENDER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PASSPORT_NUMBER end) as PASSPORT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_EXISTING_DISEASE_DESCRIPTION end) as PRE_EXISTING_DISEASE_DESCRIPTION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK
),

hashed as (
    select
        *,
        case when MEMBER_ADDITION_INDICATOR is not null or RELATIONSHIP_TO_PROPOSER is not null or MEMBER_TYPE is not null or MEMBER_NAME is not null or DATE_OF_BIRTH is not null or GENDER is not null or PASSPORT_NUMBER is not null or PRE_EXISTING_DISEASE_DESCRIPTION is not null
                     then md5(upper(coalesce(cast(MEMBER_ADDITION_INDICATOR as varchar), '') || '|' || coalesce(cast(RELATIONSHIP_TO_PROPOSER as varchar), '') || '|' || coalesce(cast(MEMBER_TYPE as varchar), '') || '|' || coalesce(cast(MEMBER_NAME as varchar), '') || '|' || coalesce(cast(DATE_OF_BIRTH as varchar), '') || '|' || coalesce(cast(GENDER as varchar), '') || '|' || coalesce(cast(PASSPORT_NUMBER as varchar), '') || '|' || coalesce(cast(PRE_EXISTING_DISEASE_DESCRIPTION as varchar), '')))
                end as SAT_RISK_PERSON_MEMBER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_RISK_OBJECT_HK is not null
  and SAT_RISK_PERSON_MEMBER_HASHDIFF is not null
